    private void levelUpPassively(int targetLevel) {
        this.passiveLevelBlood = 0;
        boolean leveled = FactionPlayerHandler.get(this.player).setFaction(FactionUpdate.builder().faction(ModFactions.VAMPIRE).level(targetLevel));
        if (leveled && this.player instanceof ServerPlayer serverPlayer) {
            FactionSounds.playLevelUpSoundServer(serverPlayer);
        }
    }

    @Override
    public void levelChanged(FactionUpdate changes) {
        this.applyEntityAttributes();
        this.passiveLevelBlood = 0;
        var newLevel = changes.getLevel();

        int maxBlood = 20;

        if (newLevel > 13) {
            maxBlood = 40;
        } else if (newLevel > 9) {
            maxBlood = 34;
        } else if (newLevel > 6) {
            maxBlood = 30;
        } else if (newLevel > 3) {
            maxBlood = 26;
        }
        this.bloodStats.setMaxBlood(maxBlood);

        super.levelChanged(changes);
    }

    @Override
    protected void onLevelChanged(int level) {
        ScoreboardUtil.updateScoreboard(this.player, ScoreboardUtil.VAMPIRE_LEVEL_CRITERIA, level);
        applyLevelModifiersA(level);
        applyLevelModifiersB(level, false);
        if (this.player.getHealth() > this.player.getMaxHealth()) {
            this.player.setHealth(this.player.getMaxHealth());
        }
        updateNaturalArmor(level);
    }

